validation_script:
import hashlib, json, os, shutil, subprocess, time
from pathlib import Path
root=Path.cwd(); out=root/'build/ch4-compiler-final'
report_path=root/'benchmarks/results/2026-10-09-ch4-compiler.json'
node='/nix/store/5a8ysg1jnj8jmzzyfcfw7rvpvnp5rfpa-nodejs-24.15.0/bin/node'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def sources():
    names=subprocess.check_output(['git','ls-files','src','bootstrap','runtime','runner','scripts/run-wasi.mjs'],text=True).splitlines()
    return {name:digest(root/name) for name in names}
report={'status':'running','note':'Final-source capability/correctness checks, not isolated timing benchmarks. Chibi remains the build host.', 'base_revision':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'source_sha256':sources(),'node_version':subprocess.check_output([node,'--version'],text=True).strip(),'steps':[],'equivalence':[]}
def save(): report_path.write_text(json.dumps(report,indent=2)+'\n')
def run(name,cmd,env=None,allow_failure=False):
    print(name,flush=True); start=time.monotonic()
    p=subprocess.run(list(map(str,cmd)),cwd=root,env={**os.environ,**(env or {})},text=True,capture_output=True,timeout=900)
    report['steps'].append({'name':name,'command':list(map(str,cmd)),'seconds':time.monotonic()-start,'status':p.returncode,'stdout':p.stdout,'stderr':p.stderr});save()
    if p.returncode and not allow_failure: raise RuntimeError(f'{name}: {p.returncode}\n{p.stderr}\n{p.stdout}')
    return p

def build(name,ir,target):
    run(name,['cargo','build','--offline','--release','-p','snail-runner','--target',target],{'SNAIL_LLVM_IR':str(ir),'CARGO_TARGET_DIR':str(out/'cargo')})
    source=out/'cargo'/target/'release'/('snail-runner.wasm' if target.startswith('wasm') else 'snail-runner')
    dest=out/(name+('.wasm' if target.startswith('wasm') else ''))
    shutil.copy2(source,dest);return dest

def equivalent(name,actual,expected):
    item={'name':name,'actual_sha256':digest(actual),'expected_sha256':digest(expected),'byte_equal':actual.read_bytes()==expected.read_bytes(),'bytes':actual.stat().st_size}
    report['equivalence'].append(item);save()
    if not item['byte_equal']:raise RuntimeError(f'{name}: emitted LLVM differs')

try:
    compiler=out/'compiler.ll'
    run('emit-compiler',[root/'snail-compile',root/'src/snail-scheme/compile.scm',compiler])
    native=build('compiler-native',compiler,'i686-unknown-linux-musl')
    wasm=build('compiler-wasm',compiler,'wasm32-wasip1')
    report['compiler_ir_sha256']=digest(compiler)
    report['compiler_binaries']={'native':digest(native),'wasi':digest(wasm)}
    wasi=[node,'--no-warnings',root/'scripts/run-wasi.mjs',wasm]
    native_ir=out/'native-compiler.ll'
    run('native-compile-itself',[native,root,root/'src/snail-scheme/compile.scm',native_ir,'--timing'],{'SNAIL_RUNTIME_STATS':'1'})
    equivalent('native-self',native_ir,compiler)
    run('verify-native-self',['opt','-passes=verify','-disable-output',native_ir])
    wasm_ir=out/'wasm-compiler.ll'
    default=run('default-node-wasm-compile-itself',[*wasi,root,root/'src/snail-scheme/compile.scm',wasm_ir,'--timing'],allow_failure=True)
    if default.returncode:
        if 'Fatal process out of memory: Zone' not in default.stderr:raise RuntimeError('unexpected default Node failure')
        report['host_limitation']='Node24.15.0 exhausts its V8 optimizer Zone on this compiler-sized module. Explicit --liftoff-only works; normal CLI and benchmark host flags are unchanged.'
        wasi=[node,'--liftoff-only','--no-warnings',root/'scripts/run-wasi.mjs',wasm]
        run('baseline-tier-wasm-compile-itself',[*wasi,root,root/'src/snail-scheme/compile.scm',wasm_ir,'--timing'],{'SNAIL_RUNTIME_STATS':'1'})
    equivalent('wasm-self',wasm_ir,compiler)
    run('verify-wasm-self',['opt','-passes=verify','-disable-output',wasm_ir])
    host_fib=out/'host-fibonacci.ll'
    run('host-fibonacci',[root/'snail-compile',root/'examples/fibonacci.scm',host_fib])
    for target,cmd,triple in [('native',[native],'i686-unknown-linux-musl'),('wasm',wasi,'wasm32-wasip1')]:
        ir=out/f'{target}-fibonacci.ll'
        run(f'{target}-emit-fibonacci',[*cmd,root,root/'examples/fibonacci.scm',ir,'--timing'])
        equivalent(f'{target}-fibonacci',ir,host_fib)
        executable=build(f'fibonacci-{target}',ir,triple)
        execute=[executable] if target=='native' else [node,'--no-warnings',root/'scripts/run-wasi.mjs',executable]
        result=run(f'run-fibonacci-{target}',execute)
        if not result.stdout.startswith('fib(25) = 75025\n'):raise RuntimeError('wrong Fibonacci result')
    if sources()!=report['source_sha256']:raise RuntimeError('production sources changed during capability checks')
    report['status']='passed_with_host_limitation' if 'host_limitation' in report else 'passed'
except Exception as e:
    report['status']='failed';report['error']=str(e);raise
finally:
    report['validation_script']=Path(__file__).read_text();save()
